"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["79585"],{44821(e){e.exports=JSON.parse('{"id":"V4-039","slug":"free-rider-problem","term":"Free Rider Problem","also_known_as":[],"difficulty":"Intermediate","definition":"The free rider problem occurs when people can benefit from a good or service without paying for it, which leads to too little of it being provided, because everyone has an incentive to let others pay.","explanation":["The problem arises with goods that are non-excludable, meaning it is difficult to stop people who do not pay from using them. Public goods, such as national defence, street lighting and clean air, are classic examples.","For example, if a neighbourhood relied on voluntary payments to fund street lighting, many residents might choose not to pay, knowing they would still benefit if others paid. If enough people think this way, the lighting may never be funded.","The free rider problem explains why many public goods are funded through taxation, which requires everyone to contribute. It also appears in other situations: union members who benefit from negotiated pay rises without paying dues, shareholders who benefit from activist campaigns without contributing, and countries that benefit from others\u2019 efforts to reduce carbon emissions without making their own.","Solutions include government provision funded by taxes, compulsory contributions, making goods excludable, for example through subscriptions, and social norms that encourage contribution."],"note":"","total":1725,"prev":{"slug":"free-float","term":"Free Float"},"next":{"slug":"free-trade","term":"Free Trade"}}')}}]);